#!/usr/bin/env node
/**
 * Issue #12 stress-matrix runner.
 *
 * Runs every case in `tests/issue-12-matrix.mjs` and writes two artefacts:
 *
 *   artifacts/stress-matrix/latest.json   machine-readable, for CI and diffing
 *   docs/issue-12-report.md               the readable record, checked in
 *
 * Both are generated, never edited by hand. The report is the evidence the issue
 * asks for ("Record exact outputs and evidence"), and it is regenerated by
 * `npm run stress:matrix`, so a stale report is a stale command, not a stale
 * claim.
 *
 * Offline by construction: it imports the compiler, reviewer and guard directly
 * and never talks to Figma. Cases that need a live render say BLOCKED rather
 * than reporting a result nobody gathered.
 *
 * Usage: npm run stress:matrix
 */
import { mkdir, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import { runMatrix, summarise, CASES, BLOCKED_CASES, OPEN_CASES } from "../tests/issue-12-matrix.mjs";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const jsonPath = resolve(root, process.env.FIGDES_STRESS_OUTPUT ?? "artifacts/stress-matrix/latest.json");
const mdPath = resolve(root, "docs/issue-12-report.md");

const results = runMatrix();
const totals = summarise(results);
const now = new Date().toISOString();

const MARK = { PASS: "PASS", FAIL: "FAIL", BLOCKED: "BLOCKED" };

/** One table row, with pipes in the text escaped so the table survives. */
const cell = (s) => String(s ?? "").replace(/\|/g, "\\|").replace(/\n+/g, " ").trim();

function tableFor(group) {
  const rows = results.filter((r) => r.group === group);
  if (rows.length === 0) return "_No cases in this group._\n";
  const lines = [
    "| ID | Case | Status | Measured result |",
    "| --- | --- | --- | --- |",
    ...rows.map((r) => `| **${r.id}** | ${cell(r.title)} | ${MARK[r.status]} | ${cell(r.detail)} |`),
    "",
  ];
  return lines.join("\n");
}

const openDetail = results
  .filter((r) => r.status === "FAIL")
  .map((r) => {
    const c = OPEN_CASES.find((x) => x.id === r.id);
    return [
      `### ${r.id} — ${r.title}`,
      "",
      `**Requirement.** ${r.requirement}`,
      "",
      `**Known issue.** ${c?.knownIssue ?? "Not recorded — this is a bug in the matrix itself."}`,
      "",
      `**Measured.** ${r.detail}`,
      "",
      "```json",
      JSON.stringify(r.raw, null, 2),
      "```",
      "",
    ].join("\n");
  })
  .join("\n");

const md = `# Issue #12 — stress matrix report

Generated by \`npm run stress:matrix\` on ${now}. Do not edit by hand; edit
\`tests/issue-12-matrix.mjs\` and regenerate.

**${totals.total} cases — ${totals.pass} PASS, ${totals.fail} FAIL, ${totals.blocked} BLOCKED.**

Every case has a stable id, a deterministic input built from literals, a measured
result, and an explicit status. This runner is offline: it drives the compiler,
the reviewer and the guard directly and never contacts Figma, so no result in
this report is a live render or a live apply.

## A. Compiler and geometry

${tableFor("compiler")}## B. Design QA and guardrails

${tableFor("guardrails")}## C. Live render/apply gate

${tableFor("live")}
These four cannot be satisfied by running more offline code. They need a write to
a disposable frame in the live file and a read back. They report BLOCKED and
claim no evidence, which is the point: acceptance criterion 8 forbids describing
a dry run as a live render, and a case that quietly reported PASS would do
exactly that.

## Open failures

Each of these is measured, not predicted. They are kept here rather than deleted
so the failure stays visible.

${openDetail || "_None._"}
## How this report is kept honest

- \`tests/issue-12-stress.test.mjs\` asserts every case in \`CASES\` passes and
  every case in \`OPEN_CASES\` still fails. A silent fix fails CI and forces the
  issue to be closed deliberately rather than quietly.
- A \`BLOCKED\` case must state why it is blocked and its raw payload must say it
  holds no evidence. Both are asserted.
- A \`PASS\` case must carry a non-empty raw payload. Both are asserted.
- \`npm test\` runs the matrix alongside the rest of the suite.
`;

await mkdir(dirname(jsonPath), { recursive: true });
await writeFile(jsonPath, JSON.stringify({ generatedAt: now, totals, results }, null, 2));
await mkdir(dirname(mdPath), { recursive: true });
await writeFile(mdPath, md);

console.log(`stress matrix: ${totals.pass} PASS, ${totals.fail} FAIL, ${totals.blocked} BLOCKED (${totals.total} total)`);
console.log(`  cases   ${CASES.length} passing, ${OPEN_CASES.length} open, ${BLOCKED_CASES.length} blocked`);
for (const r of results.filter((x) => x.status === "FAIL")) console.log(`  FAIL    ${r.id}: ${r.detail.slice(0, 110)}`);
console.log(`  json    ${jsonPath}`);
console.log(`  report  ${mdPath}`);

if (process.argv.includes("--strict")) process.exit(totals.fail > 0 ? 1 : 0);
